package com.javasmyths.highguard;
import org.springframework.stereotype.Controller;import org.springframework.web.bind.annotation.*;import org.springframework.web.bind.WebDataBinder;import org.springframework.validation.BindingResult;import org.springframework.ui.Model;import org.springframework.http.*;import org.springframework.web.multipart.MultipartFile;
import javax.servlet.http.HttpSession;import java.util.*;import java.io.*;import java.nio.charset.StandardCharsets;
@Controller public class HighGuardController {
 private final ShipStore store;public HighGuardController(ShipStore store){this.store=store;}
 @org.springframework.beans.factory.annotation.Value("${highguard.portal-url:http://192.168.1.187:8080/traveller/}") private String portalUrl;
 @org.springframework.beans.factory.annotation.Value("${highguard.book2-url:http://localhost:18083/}") private String book2Url;
 @org.springframework.beans.factory.annotation.Value("${highguard.public-hosting:false}") private boolean publicHosting;
 @ModelAttribute public void hosting(Model m){m.addAttribute("portalUrl",portalUrl);m.addAttribute("book2Url",book2Url);m.addAttribute("storageNotice",publicHosting?"High Guard records are stored on DoxyLabs and shared with visitors. Do not enter private information.":"High Guard records are stored locally on this computer.");m.addAttribute("book2LibraryLabel",publicHosting?"DoxyLabs Book 2 library":"Local Book 2 library");m.addAttribute("book2LibraryNotice",publicHosting?"Read-only access to the shared Book 2 library. Import creates a separate High Guard copy.":"Read-only access to saved ships on this computer.");}
 @ModelAttribute("design") public Design bindingDesign(){Design d=new Design();d.batteries.clear();d.craft.clear();return d;}
 @InitBinder("design") public void binder(WebDataBinder b){b.initDirectFieldAccess();b.setAutoGrowCollectionLimit(40);b.setAllowedFields("id","name","shipClass","type","computer","spinal","purpose","starport","hull","tl","configuration","jump","maneuver","power","armor","damper","meson","globe","auxBridges","rooms","lowBerths","emergencyBerths","passengers","lowPassengers","troops","extraCrew","launchTubes","fuel","cargo","extraCapacitors","otherTons","otherMcr","budget","dropTanks","scoops","purifier","military","frozenWatch","repeatClass","navalArchitect","artifactPermission","importReviewed","batteries[*].weapon","batteries[*].mounts","batteries[*].weaponsPerMount","batteries[*].mountsPerBattery","craft[*].name","craft[*].kind","craft[*].tons","craft[*].mcr","craft[*].quantity","craft[*].crew");}
 String csrf(HttpSession s){String t=(String)s.getAttribute("csrf");if(t==null){t=UUID.randomUUID().toString();s.setAttribute("csrf",t);}return t;}
 void check(HttpSession s,String token){if(!csrf(s).equals(token))throw new IllegalArgumentException("This form expired. Reload the page and try again.");}
 void provenance(Design d,HttpSession s){Design old=(Design)s.getAttribute("draft");if(old!=null){d.sourceName=old.sourceName;d.sourceJson=old.sourceJson;d.sourceHash=old.sourceHash;d.importNotes=new ArrayList<>(old.importNotes);}}
 HighGuardRules.Report report(Design d,BindingResult binding){HighGuardRules.Report r=HighGuardRules.calculate(d);if(binding!=null&&binding.hasErrors()){r.valid=false;r.errors.add("Some inputs are not valid numbers. Review your entries.");}return r;}
 String page(Design d,HighGuardRules.Report r,HttpSession session,Model m){session.setAttribute("draft",d);m.addAttribute("d",d);m.addAttribute("r",r);m.addAttribute("csrf",csrf(session));m.addAttribute("configs",Catalog.CONFIG);m.addAttribute("computers",Catalog.COMPUTERS);m.addAttribute("weapons",Catalog.WEAPONS);m.addAttribute("majors",Catalog.MAJORS);return "builder";}
 @GetMapping("/") public String home(@RequestParam(required=false)String id,@RequestParam(required=false)String preset,HttpSession session,Model model)throws IOException{Design d=id!=null?store.read(id).design:preset!=null?Design.preset(preset):(Design)session.getAttribute("draft");if(d==null)d=new Design();return page(d,report(d,null),session,model);}
 @PostMapping("/") public String calculate(@ModelAttribute("design")Design d,BindingResult b,@RequestParam String csrf,HttpSession s,Model m){check(s,csrf);provenance(d,s);return page(d,report(d,b),s,m);}
 @PostMapping("/calculate") @ResponseBody public HighGuardRules.Report live(@ModelAttribute("design")Design d,BindingResult b,@RequestParam String csrf,HttpSession s){check(s,csrf);provenance(d,s);return report(d,b);}
 @PostMapping("/preview") public String preview(@ModelAttribute("design")Design d,BindingResult b,@RequestParam String csrf,HttpSession s,Model m){check(s,csrf);provenance(d,s);m.addAttribute("d",d);m.addAttribute("r",report(d,b));return "builder :: report";}
 @PostMapping("/save") public String save(@ModelAttribute("design")Design d,BindingResult b,@RequestParam String csrf,@RequestParam(defaultValue="false")boolean copy,HttpSession s,Model m)throws IOException{check(s,csrf);provenance(d,s);HighGuardRules.Report r=report(d,b);if(!r.valid)return page(d,r,s,m);if(copy)d.id="";ShipStore.Saved saved=store.save(d);s.setAttribute("draft",d);return "redirect:/?id="+saved.design.id+"&saved";}
 @GetMapping("/library") public String library(Model m)throws IOException{m.addAttribute("ships",store.list());return "library";}
 @GetMapping("/import") public String imports(HttpSession s,Model m)throws IOException{m.addAttribute("sources",store.book2List());m.addAttribute("csrf",csrf(s));return "import";}
 @PostMapping("/import") public String convert(@RequestParam String csrf,@RequestParam(required=false)String sourceId,@RequestParam(required=false)MultipartFile file,HttpSession s,Model m)throws IOException{check(s,csrf);try{byte[] bytes=sourceId!=null&&!sourceId.isEmpty()?store.book2Read(sourceId):file!=null?file.getBytes():new byte[0];Design d=Book2Import.convert(bytes);return page(d,report(d,null),s,m);}catch(Exception e){m.addAttribute("importError",e instanceof IllegalArgumentException?e.getMessage():"Could not read that Book 2 JSON export.");return imports(s,m);}}
 @GetMapping("/ships/{id}.json") public ResponseEntity<byte[]> export(@PathVariable String id)throws IOException{return ResponseEntity.ok().contentType(MediaType.APPLICATION_JSON).header("Content-Disposition","attachment; filename=high-guard-"+id+".json").body(store.export(id));}
 @GetMapping("/source") public ResponseEntity<byte[]> source(HttpSession s){Design d=(Design)s.getAttribute("draft");if(d==null||d.sourceJson.isEmpty())return ResponseEntity.notFound().build();return ResponseEntity.ok().contentType(MediaType.APPLICATION_JSON).header("Content-Disposition","attachment; filename=original-book2-ship.json").body(d.sourceJson.getBytes(StandardCharsets.UTF_8));}
 @GetMapping("/health") @ResponseBody public Map<String,Object> health(){Map<String,Object> r=new LinkedHashMap<>();r.put("ok",true);r.put("app","high-guard");r.put("rules","Classic Traveller Book 5 (1980)");return r;}
 @ExceptionHandler(IllegalArgumentException.class) @ResponseStatus(HttpStatus.BAD_REQUEST) public String invalid(Model m){m.addAttribute("message","The request was invalid or its form expired. Your saved ships remain intact.");return "error";}
 @ExceptionHandler(java.nio.file.NoSuchFileException.class) @ResponseStatus(HttpStatus.NOT_FOUND) public String missing(Model m){m.addAttribute("message","That ship could not be found.");return "error";}
 @ExceptionHandler(IOException.class) @ResponseStatus(HttpStatus.SERVICE_UNAVAILABLE) public String io(Model m){m.addAttribute("message","Storage could not complete this request. Your existing save was preserved.");return "error";}
}
